      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Gait and sensation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Gait and sensation grossly normal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Tiredness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient mentions being tired all the time."
      }
    },
